#!/usr/bin/env node
// Release bundler: inlines every record in the sharded data/ tree into one
// classic script, data/data.bundle.js, assigning to window.LINEAGE_DATA.
// Not an ES module: file:// origins apply CORS checks to module loads the
// same way they block fetch(), so a plain <script src> tag is required for
// the release build to work from disk in every major browser. See
// docs/m1-architecture.md section 3 and ASSUMPTIONS.md A18.
// Run: node tools/bundle.js
import { readFileSync, writeFileSync } from 'node:fs';
import { join, dirname } from 'node:path';
import { fileURLToPath } from 'node:url';
import { writeManifest, SHARD_TYPES } from './manifest.js';

const ROOT = join(dirname(fileURLToPath(import.meta.url)), '..');
const DATA_DIR = join(ROOT, 'data');

const manifest = writeManifest(DATA_DIR);

const bundle = {};
for (const shard of SHARD_TYPES) {
  bundle[shard] = {};
  for (const id of manifest[shard]) {
    const path = join(DATA_DIR, shard, `${id}.json`);
    bundle[shard][id] = JSON.parse(readFileSync(path, 'utf8'));
  }
}

const out = `// Generated by tools/bundle.js. Do not edit by hand.
window.LINEAGE_DATA = ${JSON.stringify(bundle, null, 2)};
`;

const outPath = join(DATA_DIR, 'data.bundle.js');
writeFileSync(outPath, out);
console.log(`Wrote ${outPath} (${Object.values(bundle).reduce((n, s) => n + Object.keys(s).length, 0)} records)`);
